package kz.zani.mobile

import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.*
import kotlinx.coroutines.test.*
import kz.zani.mobile.core.*
import kz.zani.mobile.data.*
import kz.zani.mobile.ui.*
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test

@OptIn(ExperimentalCoroutinesApi::class)
class InboxSelfAssignmentTest {
    private fun fixture(name:String)=javaClass.classLoader!!.getResourceAsStream("fixtures/$name.json")!!.bufferedReader().use {it.readText()}
    private fun context(o:JSONObject)=InboxConversationFilesContext(o.getInt("business"),o.getInt("conversation"),o.getInt("epoch"),o.getInt("revision"))
    private fun repository()=APIReadRepository(ReadTransport {q->val name=if(q.path=="/api/mobile/v1/inbox/")"inbox-${q.query["business"]}"else "inbox-${q.query["business"]}-${q.path.trimEnd('/').substringAfterLast('/')}";ReadResponse(200,fixture(name))})
    private fun files()=APIInboxConversationFilesRepository(FixtureInboxConversationFilesTransport.fromJSON(fixture("inbox-conversation-files")))
    private fun source()=APIInboxSelfAssignmentRepository(FixtureInboxSelfAssignmentReadTransport.fromJSON(fixture("inbox-self-assignment")))
    private class Held(override val grants:List<SyntheticInboxSelfAssignmentGrant>):SyntheticInboxSelfAssignmentPort {val attempts=mutableListOf<InboxSelfAssignmentAttempt>();val pending=mutableListOf<CompletableDeferred<SyntheticInboxSelfAssignmentOutcome>>();override suspend fun execute(a:InboxSelfAssignmentAttempt):SyntheticInboxSelfAssignmentOutcome {attempts+=a;return CompletableDeferred<SyntheticInboxSelfAssignmentOutcome>().also {pending+=it}.await()}}
    private class ReplyPort(override val grants:List<SyntheticInboxReplyGrant>):SyntheticInboxReplyPort {var calls=0;override suspend fun execute(attempt:InboxReplyAttempt):SyntheticInboxReplyOutcome {++calls;return SyntheticInboxReplyOutcome.Unknown}}
    private class HandoffPort(override val grants:List<SyntheticHandoffGrant>):SyntheticHandoffPort {var calls=0;override suspend fun execute(attempt:HandoffAttempt):SyntheticHandoffOutcome {++calls;return SyntheticHandoffOutcome.Unknown}}
    private class RetryPort(override val grants:List<SyntheticInboxRetryGrant>):SyntheticInboxRetryPort {var calls=0;override suspend fun execute(attempt:InboxRetryAttempt):SyntheticInboxRetryOutcome {++calls;return SyntheticInboxRetryOutcome.Unknown}}
    @Test fun exactSourcePlain200EmptyBodyAndActorUnknownLedger()=runTest {
        val d=JSONObject(fixture("inbox-self-assignment"));val c=context(d.getJSONObject("context"));val cases=d.getJSONArray("source_cases")
        for(i in 0 until cases.length()){val x=cases.getJSONObject(i);assertEquals(x.getString("name"),x.getBoolean("valid"),InboxSelfAssignmentSource.decode(x.getString("response_json"),context(x.getJSONObject("context")))!=null)}
        val s=InboxSelfAssignmentSource.decode(d.getString("source_json"),c)!!;val port=FixtureInboxSelfAssignmentPort.fromJSON(fixture("inbox-self-assignment"));val auth=port.grants[0].authorization(c)!!;val r=InboxSelfAssignmentReview(s,auth,1);val ledger=InboxSelfAssignmentLedger();val a=ledger.begin(r)!!
        assertEquals("{}",a.preparedBody());assertEquals("/api/inbox/conversations/901/assign/",a.path);assertTrue(a.headers.isEmpty());assertTrue(a.query.isEmpty());assertNull(ledger.begin(r));assertFalse(ledger.acknowledge(auth,ledger.visible(auth)!!))
        val receipts=d.getJSONArray("receipt_cases");for(i in 0 until receipts.length()){val x=receipts.getJSONObject(i);assertEquals(x.getString("name"),x.getBoolean("valid"),InboxSelfAssignmentReceipt.decode(x.getString("response_json"),a)!=null)}
        ledger.complete(a,port.execute(a));val response=ledger.visible(auth)!!;assertEquals(InboxSelfAssignmentPhase.RESPONSE,response.phase);assertEquals(5001,response.result!!.source.assignedTo);assertNull(response.attempt.review.source.assignedTo);ledger.complete(a,SyntheticInboxSelfAssignmentOutcome.Unknown);assertEquals(response,ledger.visible(auth));assertTrue(ledger.acknowledge(auth,response));assertEquals(1,ledger.records.size)
        val second=ledger.begin(r)!!;ledger.complete(second,SyntheticInboxSelfAssignmentOutcome.Unknown);val unknown=ledger.visible(auth)!!;assertNull(ledger.begin(r));assertFalse(ledger.acknowledge(auth,unknown))
        val next=c.copy(epoch=2,revision=2);val na=port.grants[0].authorization(next)!!;val matching=InboxSelfAssignmentSource.decode(d.getString("response_json"),next)!!;assertEquals(unknown,ledger.visible(na));assertNull(ledger.begin(InboxSelfAssignmentReview(matching,na,2)));assertEquals(second,ledger.records[1].attempt)
        val other=SyntheticInboxSelfAssignmentGrant(101,901,6002,true,true).authorization(next)!!;assertNull(ledger.visible(other));assertTrue(ledger.blocked(101,901));assertNull(ledger.begin(InboxSelfAssignmentReview(matching,other,3)));assertFalse(ledger.blocked(202,951))
        for(g in listOf(SyntheticInboxSelfAssignmentGrant(101,901,5001,false,true),SyntheticInboxSelfAssignmentGrant(101,901,5001,true,false),SyntheticInboxSelfAssignmentGrant(202,901,5001,true,true),SyntheticInboxSelfAssignmentGrant(101,951,5001,true,true),SyntheticInboxSelfAssignmentGrant(101,901,0,true,true)))assertNull(g.authorization(c))
        for(status in listOf(201,400,403,409,500)){val l=InboxSelfAssignmentLedger();val t=l.begin(r)!!;l.complete(t,SyntheticInboxSelfAssignmentOutcome.Response(status,d.getString("response_json")));assertEquals(InboxSelfAssignmentPhase.UNKNOWN,l.visible(auth)!!.phase);assertFalse(l.acknowledge(auth,l.visible(auth)!!))}
        val invalid=InboxSelfAssignmentReview(s.copy(updatedAt=""),auth,4);assertFalse(invalid.valid);assertNull(InboxSelfAssignmentLedger().begin(invalid))
    }
    @Test fun actualParentPendingKnownUnknownRereadABAAndDirectSiblingBarriers()=runTest {
        Dispatchers.setMain(StandardTestDispatcher(testScheduler));val fixturePort=FixtureInboxSelfAssignmentPort.fromJSON(fixture("inbox-self-assignment"));val held=Held(fixturePort.grants);var matching=false;val calls=mutableListOf<ReadRequest>();val base=FixtureInboxSelfAssignmentReadTransport.fromJSON(fixture("inbox-self-assignment"));val source=APIInboxSelfAssignmentRepository(ReadTransport {q->calls+=q;if(matching && q.path=="/api/inbox/conversations/901/")ReadResponse(200,JSONObject(fixture("inbox-self-assignment")).getString("response_json"))else base.get(q)})
        val reply=ReplyPort(FixtureInboxReplyPort(fixture("inbox-reply-outcome")).grants);val handoff=HandoffPort(FixtureHandoffPort(fixture("inbox-handoff-outcome")).grants);val retry=RetryPort(FixtureInboxRetryPort(fixture("inbox-retry-message")).grants)
        val m=InboxViewModel(repository(),replySubmission=reply,handoffSubmission=handoff,files=files(),messageFiles=APIInboxMessageFilesRepository(FixtureInboxRetryReadTransport(fixture("inbox-retry-message"))),retrySubmission=retry,assignmentRead=source,assignmentSubmission=held)
        try {
            m.load(101,421);runCurrent();m.open(901);runCurrent();val original=m.state.thread;val child=m.fileMetadata!!;val replyContext=m.reply.state.context!!;m.openFiles(m.filesEntryControl);assertTrue(calls.isEmpty());assertFalse(child.canPrepareAssignment);child.loadAssignment(child.control);val observed=child.assignmentSource!!;val old=child.control;child.prepareAssignment(child.control);val r=child.assignmentReview!!;val control=child.control;val reads=calls.toList();child.loadAssignment(child.control);child.load(child.control);child.submitAssignment(r,old);child.backAssignment(old);assertEquals(r,child.assignmentReview);assertEquals(reads,calls);assertTrue(held.attempts.isEmpty())
            val job=launch {child.submitAssignment(r,control)};runCurrent();val pending=child.assignmentRecord!!;child.submitAssignment(r,child.control);child.acknowledgeAssignment(pending,child.control);assertEquals(1,held.attempts.size);assertTrue(m.assignmentCommandsBlocked);m.closeFiles(m.filesPresentationControl);m.openReply(replyContext,m.control);m.openHandoff(m.handoff.entryControl,m.control);assertNull(m.reply.control);assertNull(m.handoff.control)
            m.reply.open(replyContext);m.reply.update(" Retained reply ",m.reply.inputControl);m.reply.prepare(m.reply.control);assertFalse(m.reply.canSubmit);m.reply.submit(m.reply.state.review!!,m.reply.control);assertEquals(0,m.reply.retainedAttemptCount);assertEquals(0,reply.calls);m.reply.close(m.reply.returnControl)
            m.handoff.open(m.handoff.entryControl);m.handoff.update(" Retained handoff ",m.handoff.inputControl);m.handoff.prepare(m.handoff.control);assertFalse(m.handoff.canSubmit);m.handoff.submit(m.handoff.state.review!!,m.handoff.control);m.handoff.back(m.handoff.returnControl);m.handoff.back(m.handoff.returnControl);assertEquals(0,handoff.calls)
            m.openMessageFiles(m.messageFilesEntryControl(m.state.thread!!.messages[1]));val message=m.messageMetadata!!;message.load(message.control);message.prepareRetry(message.control);assertFalse(message.canPrepareRetry);assertNull(message.retryReview);assertEquals(0,retry.calls);m.closeMessageFiles(m.messageFilesPresentationControl)
            m.openFiles(m.filesEntryControl);child.loadAssignment(child.control);assertEquals(reads,calls);assertEquals(pending,child.assignmentRecord);held.pending[0].complete(fixturePort.execute(held.attempts[0]));job.join();val response=child.assignmentRecord!!;assertEquals(InboxSelfAssignmentPhase.RESPONSE,response.phase);assertEquals(observed,response.attempt.review.source);assertEquals(original,m.state.thread);child.acknowledgeAssignment(response,control);assertEquals(response,child.assignmentRecord);child.acknowledgeAssignment(response,child.control);assertFalse(m.assignmentCommandsBlocked);assertEquals(1,child.retainedAssignmentCount)
            child.loadAssignment(child.control);child.prepareAssignment(child.control);val ur=child.assignmentReview!!;val uc=child.control;val uj=launch {child.submitAssignment(ur,uc)};runCurrent();held.pending[1].completeExceptionally(IllegalStateException("synthetic failure"));uj.join();val unknown=child.assignmentRecord!!;matching=true;child.acknowledgeAssignment(unknown,child.control);child.loadAssignment(child.control);child.prepareAssignment(child.control);assertEquals(5001,child.assignmentSource!!.assignedTo);assertNull(child.assignmentReview);assertFalse(child.canPrepareAssignment);assertEquals(unknown,child.assignmentRecord);assertEquals(2,held.attempts.size);assertNull(unknown.attempt.review.source.assignedTo)
            m.closeFiles(m.filesPresentationControl);m.load(202,422);runCurrent();m.open(951);runCurrent();m.openFiles(m.filesEntryControl);child.loadAssignment(child.control);assertNull(child.assignmentRecord);assertTrue(child.canPrepareAssignment);m.closeFiles(m.filesPresentationControl);m.load(101,423);runCurrent();m.open(901);runCurrent();m.openFiles(m.filesEntryControl);child.loadAssignment(child.control);assertEquals(unknown,child.assignmentRecord);assertTrue(m.assignmentCommandsBlocked);assertFalse(child.canPrepareAssignment)
        } finally {m.viewModelScope.cancel();Dispatchers.resetMain()}
    }
    @Test fun cancellationExplicitRejectionDefaultNoGrantAndLateSource()=runTest {
        Dispatchers.setMain(StandardTestDispatcher(testScheduler));val fixturePort=FixtureInboxSelfAssignmentPort.fromJSON(fixture("inbox-self-assignment"));val held=Held(fixturePort.grants);val model=InboxConversationFilesModel(files(),source(),held);val c=InboxConversationFilesContext(101,901,430,1);model.commandsBlocked={false};model.bind(c);model.open(model.control);model.loadAssignment(model.control);model.prepareAssignment(model.control);val r=model.assignmentReview!!;val ctrl=model.control;val j=launch {model.submitAssignment(r,ctrl)};runCurrent();held.pending[0].complete(SyntheticInboxSelfAssignmentOutcome.RejectedWithoutWrite);j.join();val rejected=model.assignmentRecord!!;assertEquals(InboxSelfAssignmentPhase.REJECTED,rejected.phase);model.acknowledgeAssignment(rejected,model.control);model.prepareAssignment(model.control);val cr=model.assignmentReview!!;val cc=model.control;val cj=launch {model.submitAssignment(cr,cc)};runCurrent();cj.cancelAndJoin();val unknown=model.assignmentRecord!!;assertEquals(InboxSelfAssignmentPhase.UNKNOWN,unknown.phase);assertEquals(cr,unknown.attempt.review);assertFalse(model.canPrepareAssignment)
        val noPort=InboxConversationFilesModel(files(),source());noPort.bind(c);noPort.open(noPort.control);noPort.loadAssignment(noPort.control);noPort.prepareAssignment(noPort.control);assertNotNull(noPort.assignmentSource);assertFalse(noPort.canPrepareAssignment);assertNull(noPort.assignmentReview)
        val deferred=CompletableDeferred<InboxSelfAssignmentSource>();val read=object:InboxSelfAssignmentRepository {override suspend fun source(c:InboxConversationFilesContext)=deferred.await()};val late=InboxConversationFilesModel(files(),read,fixturePort);late.commandsBlocked={false};late.bind(c);late.open(late.control);val before=late.control;val job=launch {late.loadAssignment(before)};runCurrent();late.close(late.presentation);late.bind(InboxConversationFilesContext(202,951,431,1));late.open(late.control);val after=late.control;deferred.complete(source().source(c));job.join();assertEquals(after,late.control);assertNull(late.assignmentSource);assertFalse(late.assignmentLoading);assertFalse(late.canPrepareAssignment);Dispatchers.resetMain()
    }
    @Test fun inverseUnknownPeersAndLateOwnerCompletionPreserveDraft()=runTest {
        Dispatchers.setMain(StandardTestDispatcher(testScheduler))
        val f=FixtureInboxSelfAssignmentPort.fromJSON(fixture("inbox-self-assignment"))
        try {
            for(kind in 0..2) {
                val ap=Held(f.grants);val rp=ReplyPort(FixtureInboxReplyPort(fixture("inbox-reply-outcome")).grants);val hp=HandoffPort(FixtureHandoffPort(fixture("inbox-handoff-outcome")).grants);val retry=RetryPort(FixtureInboxRetryPort(fixture("inbox-retry-message")).grants)
                val m=InboxViewModel(repository(),replySubmission=rp,handoffSubmission=hp,files=files(),messageFiles=APIInboxMessageFilesRepository(FixtureInboxRetryReadTransport(fixture("inbox-retry-message"))),retrySubmission=retry,assignmentRead=source(),assignmentSubmission=ap)
                try {
                    m.load(101,440+kind);runCurrent();m.open(901);runCurrent()
                    if(kind==0){m.openReply(m.reply.state.context!!,m.control);m.reply.update(" Unknown reply ",m.reply.inputControl);m.reply.prepare(m.reply.control);m.reply.submit(m.reply.state.review!!,m.reply.control);assertEquals(1,rp.calls);m.reply.close(m.reply.returnControl)}
                    else if(kind==1){m.openHandoff(m.handoff.entryControl,m.control);m.handoff.update(" Unknown handoff ",m.handoff.inputControl);m.handoff.prepare(m.handoff.control);m.handoff.submit(m.handoff.state.review!!,m.handoff.control);assertEquals(1,hp.calls);m.handoff.back(m.handoff.returnControl)}
                    else {m.openMessageFiles(m.messageFilesEntryControl(m.state.thread!!.messages[1]));val c=m.messageMetadata!!;c.load(c.control);c.prepareRetry(c.control);c.submitRetry(c.retryReview!!,c.control);assertEquals(1,retry.calls);m.closeMessageFiles(m.messageFilesPresentationControl)}
                    m.openFiles(m.filesEntryControl);val c=m.fileMetadata!!;c.loadAssignment(c.control);c.prepareAssignment(c.control);assertNotNull(c.assignmentSource);assertFalse(c.canPrepareAssignment);assertNull(c.assignmentReview);assertTrue(ap.attempts.isEmpty())
                } finally {m.viewModelScope.cancel()}
            }
            val held=Held(f.grants);val late=InboxViewModel(repository(),files=files(),assignmentRead=source(),assignmentSubmission=held)
            try {
                late.load(101,450);runCurrent();late.open(901);runCurrent();late.openFiles(late.filesEntryControl);val c=late.fileMetadata!!;c.loadAssignment(c.control);c.prepareAssignment(c.control);val r=c.assignmentReview!!;val ctrl=c.control;val j=launch {c.submitAssignment(r,ctrl)};runCurrent();val a=held.attempts[0];late.closeFiles(late.filesPresentationControl);late.load(202,451);runCurrent();late.open(951);runCurrent();late.openReply(late.reply.state.context!!,late.control);late.reply.update(" Business B draft ",late.reply.inputControl);val peer=late.reply.control;val read=late.state.thread;val fileControl=c.control;held.pending[0].complete(f.execute(a));j.join();assertEquals(fileControl,c.control);assertNull(c.assignmentSource);assertNull(c.assignmentRecord);assertEquals(1,c.retainedAssignmentCount);assertEquals(peer,late.reply.control);assertEquals(" Business B draft ",late.reply.state.text);assertEquals(read,late.state.thread)
            } finally {late.viewModelScope.cancel()}
        } finally {Dispatchers.resetMain()}
    }

}
